function drawTownBase(k,c,im){const P=PAL[c.id];k.fillStyle='#e3e8d5';k.fillRect(0,0,1000,740);const road='#c4c9c4',roadLine='#fcf9e9';for(const y of[228,453,678]){k.fillStyle=road;k.fillRect(0,y-17,1000,34);k.strokeStyle=roadLine;k.lineWidth=2;k.setLineDash([12,15]);k.beginPath();k.moveTo(0,y);k.lineTo(1000,y);k.stroke();k.setLineDash([])}for(const x of[250,500,750]){k.fillStyle=road;k.fillRect(x-13,0,26,740);k.strokeStyle=roadLine;k.lineWidth=2;k.setLineDash([12,15]);k.beginPath();k.moveTo(x,0);k.lineTo(x,740);k.stroke();k.setLineDash([])}for(let z=0;z<12;z++){const x=(z%4)*250,y=Math.floor(z/4)*225;k.beginPath();k.roundRect(x+13,y+10,224,196,17);k.fillStyle='#faf7e9';k.fill();k.strokeStyle='#ced7be';k.lineWidth=2;k.stroke();k.fillStyle='#d8e3c7';k.beginPath();k.ellipse(x+125,y+171,92,9,0,0,7);k.fill();imageTile(k,im,z,x+19,y+17,212,159);k.font='800 13px system-ui';k.textAlign='center';k.fillStyle='#516a5b';k.fillText(T[c.id][z][0],x+125,y+184);k.font='10px system-ui';k.fillStyle='#9a997f';k.fillText(T[c.id][z][1],x+125,y+199);if(tp[c.id]?.[z]){k.fillStyle='#8ca87b';k.beginPath();k.arc(x+216,y+27,10,0,7);k.fill();k.fillStyle='#fff7dc';k.font='bold 11px system-ui';k.fillText('✓',x+216,y+31)}}}
function viewFor(dx,dy){return Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?0:2}
function pathRoad(x,y,tx,ty){const ys=[228,453,678],xs=[250,500,750],near=(a,n)=>a.reduce((b,v)=>Math.abs(v-n)<Math.abs(b-n)?v:b),fromY=near(ys,y),toY=near(ys,ty),via=near(xs,(x+tx)/2);if(Math.abs(fromY-toY)<1)return[{x,y:fromY},{x:tx,y:toY}];return[{x,y:fromY},{x:via,y:fromY},{x:via,y:toY},{x:tx,y:toY}]}
