const vWheel=(k,x,y,r)=>{k.fillStyle='#2b3033';k.beginPath();k.arc(x,y,r,0,7);k.fill();k.fillStyle='#d4dadc';k.beginPath();k.arc(x,y,r*.42,0,7);k.fill()};
